    meaning: "\u0641\u0631\u0642 \u0627\u0644\u062C\u0647\u062F \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064A \u0628\u064A\u0646 \u0637\u0631\u0641\u064A \u0645\u0648\u0635\u0644 \u064A\u062A\u0646\u0627\u0633\u0628 \u0637\u0631\u062F\u064A\u064B\u0627 \u0645\u0639 \u0634\u062F\u0629 \u0627\u0644\u062A\u064A\u0627\u0631 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064A \u0627\u0644\u0645\u0627\u0631 \u0641\u064A\u0647 \u0639\u0646\u062F \u062B\u0628\u0648\u062A \u062F\u0631\u062C\u0629 \u0627\u0644\u062D\u0631\u0627\u0631\u0629. \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0647\u064A \u062B\u0627\u0628\u062A \u0627\u0644\u062A\u0646\u0627\u0633\u0628 \u0648\u062A\u0639\u0628\u0651\u0631 \u0639\u0646 \u0645\u062F\u0649 \u0625\u0639\u0627\u0642\u0629 \u0627\u0644\u0645\u0627\u062F\u0629 \u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u0627\u062A.",
