      { time: "10:30", title: "\u0642\u0627\u0639\u062F\u0629 \u062A\u062C\u0627\u0646\u0633 \u0627\u0644\u0623\u0628\u0639\u0627\u062F \u0648\u0627\u062E\u062A\u0628\u0627\u0631 \u0627\u0644\u0642\u0648\u0627\u0646\u064A\u0646" },
      { time: "14:45", title: "\u062A\u0637\u0628\u064A\u0642 \u0639\u0645\u0644\u064A: \u0637\u0627\u0642\u0629 \u0627\u0644\u062D\u0631\u0643\u0629 \u0648\u0627\u0644\u0628\u0646\u062F\u0648\u0644" }
