  const lessonTitle = params.lessonTitle?.trim() || "\u0642\u0627\u0646\u0648\u0646 \u0623\u0648\u0645 \u0648\u062A\u062D\u0644\u064A\u0644 \u0627\u0644\u062F\u0648\u0627\u0626\u0631";
  const explanationLevel = params.explanationLevel || "beginner";
